class AuthenticationManager {
    int ttl;
    set<pair<int, string>> expiries;
    unordered_map<string, int> tokenExpiry;
public:
    AuthenticationManager(int timeToLive) : ttl(timeToLive) {}

    void generate(string tokenId, int currentTime) {
        int expiry = currentTime + ttl;
        tokenExpiry[tokenId] = expiry;
        expiries.insert({expiry, tokenId});
    }

    void renew(string tokenId, int currentTime) {
        auto it = tokenExpiry.find(tokenId);
        if (it == tokenExpiry.end()) return;
        if (it->second <= currentTime) return;
        expiries.erase({it->second, tokenId});
        int newExpiry = currentTime + ttl;
        it->second = newExpiry;
        expiries.insert({newExpiry, tokenId});
    }

    int countUnexpiredTokens(int currentTime) {
        while (!expiries.empty() && expiries.begin()->first <= currentTime) {
            auto it = expiries.begin();
            tokenExpiry.erase(it->second);
            expiries.erase(it);
        }
        return expiries.size();
    }
};
